using System.Globalization;
using System.Security;
using System.Text;
using Avalonia;
using Avalonia.Media;

namespace NewManga.DesignSystem.Tokens;

/// <summary>
/// Serializes token values into deterministic Avalonia resource-dictionary XAML. Every generated file
/// is a pure function of <c>tokens.json</c> plus the static mapping tables, so regenerating must be
/// byte-identical (AC1). No timestamps or machine-specific paths are emitted.
/// </summary>
internal static class TokenDictionaryWriter
{
    private const string XamlNamespace = "https://github.com/avaloniaui";
    private const string XamlSchema = "http://schemas.microsoft.com/winfx/2006/xaml";

    /// <summary>Generated-file banner shared by every emitted artifact.</summary>
    internal const string Banner =
        "@generated by NewManga.DesignSystem token pipeline — do not edit by hand.";

    internal static string BrushDictionary(
        IReadOnlyList<(string Key, string RawValue)> brushes,
        string scopeDescription)
    {
        var builder = new StringBuilder(16 * 1024);
        builder.Append("<ResourceDictionary xmlns=\"").Append(XamlNamespace).AppendLine("\"")
            .Append("                    xmlns:x=\"").Append(XamlSchema).AppendLine("\">");
        AppendBanner(builder, scopeDescription);
        foreach (var (key, rawValue) in brushes.OrderBy(static entry => entry.Key, StringComparer.Ordinal))
        {
            var color = TokenValues.ToHex(TokenValues.ParseColor(rawValue));
            builder.Append("  <SolidColorBrush x:Key=\"").Append(key)
                .Append("\" Color=\"").Append(color).AppendLine("\" />");
        }

        builder.AppendLine("</ResourceDictionary>");
        return NormalizeLf(builder);
    }

    internal static string GlobalDictionary(
        IReadOnlyList<(string Key, TokenValueKind Kind, string RawValue)> tokens,
        string scopeDescription)
    {
        var builder = new StringBuilder(16 * 1024);
        builder.Append("<ResourceDictionary xmlns=\"").Append(XamlNamespace).AppendLine("\"")
            .Append("                    xmlns:x=\"").Append(XamlSchema).AppendLine("\"")
            .AppendLine("                    xmlns:sys=\"using:System\">");
        AppendBanner(builder, scopeDescription);
        foreach (var (key, kind, rawValue) in tokens.OrderBy(static entry => entry.Key, StringComparer.Ordinal))
        {
            builder.Append("  ").AppendLine(Element(key, kind, rawValue));
        }

        builder.AppendLine("</ResourceDictionary>");
        return NormalizeLf(builder);
    }

    /// <summary>
    /// Emits a dictionary whose entries are themselves theme scoped (used for high contrast, where the
    /// two palettes must stay switchable through <c>ThemeVariant</c> while the overlay is applied).
    /// </summary>
    internal static string ThemeScopedBrushDictionary(
        IReadOnlyList<(string Key, string RawValue)> darkBrushes,
        IReadOnlyList<(string Key, string RawValue)> lightBrushes,
        string scopeDescription)
    {
        var builder = new StringBuilder(32 * 1024);
        builder.Append("<ResourceDictionary xmlns=\"").Append(XamlNamespace).AppendLine("\"")
            .Append("                    xmlns:x=\"").Append(XamlSchema).AppendLine("\">");
        AppendBanner(builder, scopeDescription);
        builder.AppendLine("  <ResourceDictionary.ThemeDictionaries>");
        AppendBrushScope(builder, "Dark", darkBrushes);
        AppendBrushScope(builder, "Light", lightBrushes);
        builder.AppendLine("  </ResourceDictionary.ThemeDictionaries>");
        builder.AppendLine("</ResourceDictionary>");
        return NormalizeLf(builder);
    }

    internal static string KeysClass(IReadOnlyList<string> keys, string scopeDescription)
    {
        var root = new KeyNode();
        foreach (var key in keys.OrderBy(static value => value, StringComparer.Ordinal))
        {
            if (!key.StartsWith(TokenMap.Prefix, StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"resource key '{key}' does not start with '{TokenMap.Prefix}'");
            }

            var segments = key[TokenMap.Prefix.Length..].Split('.');
            var node = root;
            foreach (var segment in segments)
            {
                if (!node.Children.TryGetValue(segment, out var child))
                {
                    child = new KeyNode { Segment = segment, Path = node.Path.Length == 0 ? TokenMap.Prefix + segment : node.Path + "." + segment };
                    node.Children.Add(segment, child);
                }

                node = child;
            }

            node.ResourceKey = key;
        }

        var builder = new StringBuilder(16 * 1024);
        builder.AppendLine("// <auto-generated>");
        builder.Append("//   ").AppendLine(Banner);
        builder.Append("//   ").AppendLine(scopeDescription);
        builder.AppendLine("// </auto-generated>");
        builder.AppendLine();
        builder.AppendLine("namespace NewManga.DesignSystem;");
        builder.AppendLine();
        builder.AppendLine("/// <summary>");
        builder.AppendLine("/// Compile-time constants for every <c>Nm.*</c> resource key the design system publishes.");
        builder.AppendLine("/// UI code must reference these instead of string literals (AC3).");
        builder.AppendLine("/// </summary>");
        builder.AppendLine("public static class NmKeys");
        builder.AppendLine("{");
        builder.AppendLine("    /// <summary>Every published key, in ordinal order (used by conformance tests).</summary>");
        builder.AppendLine("    public static readonly string[] All =");
        builder.AppendLine("    [");
        foreach (var key in keys.OrderBy(static value => value, StringComparer.Ordinal))
        {
            builder.Append("        \"").Append(key).AppendLine("\",");
        }

        builder.AppendLine("    ];");
        AppendKeysNode(builder, root, indentLevel: 1);
        builder.AppendLine("}");
        return NormalizeLf(builder);
    }

    internal static string StatusSymbolsClass(
        IReadOnlyList<(string MemberName, string Symbol)> symbols,
        string scopeDescription)
    {
        var builder = new StringBuilder(4 * 1024);
        builder.AppendLine("// <auto-generated>");
        builder.Append("//   ").AppendLine(Banner);
        builder.Append("//   ").AppendLine(scopeDescription);
        builder.AppendLine("// </auto-generated>");
        builder.AppendLine();
        builder.AppendLine("namespace NewManga.DesignSystem;");
        builder.AppendLine();
        builder.AppendLine("/// <summary>");
        builder.AppendLine("/// Status symbols from the frozen <c>stateSymbols</c> token group. This is the single source");
        builder.AppendLine("/// of the symbol channel required by DESIGN_SYSTEM §2.2 (hue + symbol + text).");
        builder.AppendLine("/// </summary>");
        builder.AppendLine("public static class NmStatusSymbols");
        builder.AppendLine("{");
        foreach (var (memberName, symbol) in symbols.OrderBy(static entry => entry.MemberName, StringComparer.Ordinal))
        {
            builder.Append("    /// <summary>Symbol for the ").Append(memberName).AppendLine(" status.</summary>");
            builder.Append("    public const string ").Append(memberName).Append(" = \"")
                .Append(Escape(symbol)).AppendLine("\";");
            builder.AppendLine();
        }

        builder.Length -= Environment.NewLine.Length;
        builder.AppendLine();
        builder.AppendLine("}");
        return NormalizeLf(builder);
    }

    internal static string MapMarkdown(IReadOnlyList<GeneratedMappingRow> rows, string scopeDescription)
    {
        var builder = new StringBuilder(32 * 1024);
        builder.AppendLine("# Token -> Avalonia resource key map (generated)");
        builder.AppendLine();
        builder.Append("<!-- ").Append(Banner).AppendLine(" -->");
        builder.AppendLine();
        builder.AppendLine(scopeDescription);
        builder.AppendLine();
        builder.AppendLine($"Rows: {rows.Count}.");
        builder.AppendLine();
        builder.AppendLine("| Scope | DTCG token | Resource key | Kind | Raw value |");
        builder.AppendLine("|---|---|---|---|---|");
        foreach (var row in rows.OrderBy(static value => value.Scope, StringComparer.Ordinal)
                     .ThenBy(static value => value.TokenPath, StringComparer.Ordinal))
        {
            builder.Append("| ").Append(row.Scope)
                .Append(" | `").Append(row.TokenPath)
                .Append("` | `").Append(row.ResourceKey)
                .Append("` | ").Append(row.Kind.ToString())
                .Append(" | `").Append(row.RawValue.Replace("|", "\\|", StringComparison.Ordinal))
                .AppendLine("` |");
        }

        AppendMapNotes(builder);
        return NormalizeLf(builder);
    }

    /// <summary>
    /// Forces LF so generated artifacts are byte-identical regardless of the host OS or the
    /// checkout's <c>core.autocrlf</c> setting (the design-system directory pins eol=lf in
    /// .gitattributes for the same reason).
    /// </summary>
    private static string NormalizeLf(StringBuilder builder) =>
        builder.ToString().Replace("\r\n", "\n", StringComparison.Ordinal);

    /// <summary>Static naming/derivation notes appended to the generated token map (R-14 contract notes).</summary>
    private static void AppendMapNotes(StringBuilder builder)
    {
        builder.AppendLine();
        builder.AppendLine("## Naming and derivation notes (R-14, contract §2.4)");
        builder.AppendLine();
        builder.AppendLine("- `font.size.2xl` is published as `Nm.FontSize.Xxl` (frozen contract key, R-14). `Nm.FontSize.2Xl` must not exist.");
        builder.AppendLine("- `Nm.LineHeight.Display/Title/Body/Label/Meta/Data` are semantic aliases whose values are constrained to one of the frozen multipliers (1.25 / 1.45 / 1.6); the generator asserts this rule. Absolute pixel line boxes for Avalonia live in `Nm.TextLineBox.*`.");
        builder.AppendLine("- `Nm.FontTracking.*` values are **em-relative ratios**, not pixels (Avalonia 11 has no em-based letter spacing); consumers that need device pixels must multiply by their font size.");
        builder.AppendLine("- `Themes/Tokens.HighContrast.axaml` and `Themes/Density.*.axaml` are rule-derived generator extensions (contract §2.4), not second truth sources: high contrast enforces text >= 7:1 / status >= 4.5:1; density enforces Compact < Comfortable < Spacious; both are asserted at generation time.");
        builder.AppendLine("- `Nm.Color.Scrim` is a derived theme-invariant color used by Modal; it belongs to the global token dictionary and is never part of an appearance palette layer.");
        builder.AppendLine("- Material/elevation keys are reserved (`Nm.Material.*` / `Nm.Elevation.*`) and currently empty: the frozen system expresses elevation only through the five-level surface ladder.");
    }

    private static void AppendBrushScope(
        StringBuilder builder,
        string themeKey,
        IReadOnlyList<(string Key, string RawValue)> brushes)
    {
        builder.Append("    <ResourceDictionary x:Key=\"").Append(themeKey).AppendLine("\">");
        foreach (var (key, rawValue) in brushes.OrderBy(static entry => entry.Key, StringComparer.Ordinal))
        {
            var color = TokenValues.ToHex(TokenValues.ParseColor(rawValue));
            builder.Append("      <SolidColorBrush x:Key=\"").Append(key)
                .Append("\" Color=\"").Append(color).AppendLine("\" />");
        }

        builder.AppendLine("    </ResourceDictionary>");
    }

    private static void AppendBanner(StringBuilder builder, string scopeDescription)
    {
        builder.Append("  <!-- ").Append(Banner).AppendLine();
        builder.Append("       ").Append(scopeDescription).AppendLine();
        builder.AppendLine("       source: doc/design/redesign-v1/40-fusion/tokens.json (FROZEN) -->");
    }

    private static string Element(string key, TokenValueKind kind, string rawValue) => kind switch
    {
        TokenValueKind.Brush =>
            $"<SolidColorBrush x:Key=\"{key}\" Color=\"{TokenValues.ToHex(TokenValues.ParseColor(rawValue))}\" />",
        TokenValueKind.FontFamily =>
            $"<FontFamily x:Key=\"{key}\">{Escape(TokenValues.ParseFontFamily(rawValue))}</FontFamily>",
        TokenValueKind.Double =>
            $"<sys:Double x:Key=\"{key}\">{TokenValues.FormatDouble(TokenValues.ParseDimension(rawValue))}</sys:Double>",
        TokenValueKind.EmRatio =>
            $"<sys:Double x:Key=\"{key}\">{TokenValues.FormatDouble(TokenValues.ParseEmRatio(rawValue))}</sys:Double>",
        TokenValueKind.FontWeight =>
            $"<FontWeight x:Key=\"{key}\">{FontWeightName(TokenValues.ParseFontWeight(rawValue))}</FontWeight>",
        TokenValueKind.CornerRadius =>
            $"<CornerRadius x:Key=\"{key}\">{FormatCornerRadius(TokenValues.ParseCornerRadius(rawValue))}</CornerRadius>",
        TokenValueKind.Thickness =>
            $"<Thickness x:Key=\"{key}\">{FormatThickness(TokenValues.ParseThickness(rawValue))}</Thickness>",
        TokenValueKind.TimeSpan =>
            $"<sys:TimeSpan x:Key=\"{key}\">{TokenValues.FormatTimeSpan(TokenValues.ParseDuration(rawValue))}</sys:TimeSpan>",
        TokenValueKind.Boolean =>
            $"<sys:Boolean x:Key=\"{key}\">{(ParseBoolean(rawValue) ? "True" : "False")}</sys:Boolean>",
        TokenValueKind.String =>
            $"<sys:String x:Key=\"{key}\">{Escape(rawValue)}</sys:String>",
        TokenValueKind.Int32 =>
            $"<sys:Int32 x:Key=\"{key}\">{int.Parse(rawValue.Trim(), CultureInfo.InvariantCulture)}</sys:Int32>",
        _ => throw new ArgumentOutOfRangeException(nameof(kind), kind, "unsupported token value kind"),
    };

    private static bool ParseBoolean(string raw) => raw.Trim().ToLowerInvariant() switch
    {
        "true" => true,
        "false" => false,
        _ => throw new FormatException($"unsupported boolean token value '{raw}'"),
    };

    private static string FontWeightName(FontWeight weight) => weight switch
    {
        _ when weight == FontWeight.Thin => "Thin",
        _ when weight == FontWeight.ExtraLight => "ExtraLight",
        _ when weight == FontWeight.Light => "Light",
        _ when weight == FontWeight.Normal => "Normal",
        _ when weight == FontWeight.Medium => "Medium",
        _ when weight == FontWeight.SemiBold => "SemiBold",
        _ when weight == FontWeight.Bold => "Bold",
        _ when weight == FontWeight.ExtraBold => "ExtraBold",
        _ when weight == FontWeight.Black => "Black",
        _ => throw new ArgumentOutOfRangeException(nameof(weight), weight, "unsupported font weight"),
    };

    private static string FormatThickness(Thickness thickness) =>
        string.Join(',', new[]
        {
            TokenValues.FormatDouble(thickness.Left),
            TokenValues.FormatDouble(thickness.Top),
            TokenValues.FormatDouble(thickness.Right),
            TokenValues.FormatDouble(thickness.Bottom),
        });

    private static string FormatCornerRadius(CornerRadius corner) =>
        corner.IsUniform
            ? TokenValues.FormatDouble(corner.TopLeft)
            : string.Join(',', new[]
            {
                TokenValues.FormatDouble(corner.TopLeft),
                TokenValues.FormatDouble(corner.TopRight),
                TokenValues.FormatDouble(corner.BottomRight),
                TokenValues.FormatDouble(corner.BottomLeft),
            });

    private static string Escape(string value) => SecurityElement.Escape(value)
        ?? throw new ArgumentNullException(nameof(value));

    private static void AppendKeysNode(StringBuilder builder, KeyNode node, int indentLevel)
    {
        var indent = new string(' ', indentLevel * 4);
        foreach (var child in node.Children.Values)
        {
            if (child.ResourceKey is not null)
            {
                builder.Append(indent).Append("/// <summary>").Append(child.ResourceKey).AppendLine("</summary>");
                builder.Append(indent).Append("public const string ").Append(MemberName(child.Segment))
                    .Append(" = \"").Append(child.ResourceKey).AppendLine("\";");
                continue;
            }

            builder.AppendLine();
            builder.Append(indent).Append("public static class ").Append(MemberName(child.Segment));
            builder.AppendLine();
            builder.Append(indent).AppendLine("{");
            AppendKeysNode(builder, child, indentLevel + 1);
            builder.Append(indent).AppendLine("}");
        }
    }

    private static string MemberName(string segment) =>
        segment.Length > 0 && char.IsDigit(segment[0]) ? "S" + segment : segment;

    private sealed class KeyNode
    {
        public string Segment { get; init; } = string.Empty;

        public string Path { get; init; } = string.Empty;

        public string? ResourceKey { get; set; }

        public SortedDictionary<string, KeyNode> Children { get; } = new(StringComparer.Ordinal);
    }
}
